import pickletools, glob, collections
for fn in sorted(glob.glob('model_*.pkl')):
    data=open(fn,'rb').read()
    globals_ref=[]
    strings=[]
    try:
        for op,arg,pos in pickletools.genops(data):
            name=op.name
            if name in ('STACK_GLOBAL',) :
                pass
            if name in ('SHORT_BINUNICODE','UNICODE','BINUNICODE') and isinstance(arg,str):
                strings.append(arg)
            if name in ('REDUCE','INST','OBJ','NEWOBJ','NEWTRUE','BUILD'):
                globals_ref.append(name)
    except Exception as e:
        print(fn,'PARSE ERROR',e); continue
    ops=collections.Counter(globals_ref)
    print('==',fn,'size',len(data),'ops',dict(ops))
    print('   strings:', [s for s in strings if not s.startswith('layer')][:24])
EOF"}

