import pickletools, glob

def safe_scan(fn):
    data=open(fn,'rb').read()
    ops=list(pickletools.genops(data))
    globals_set=set(); strings=[]; floats=[]
    for i,(op,arg,pos) in enumerate(ops):
        if op.name=='STACK_GLOBAL':
            mod=ops[i-2][1]; nm=ops[i-1][1]
            globals_set.add(f'{mod}.{nm}')
        if op.name in ('SHORT_BINUNICODE','UNICODE','BINUNICODE'): strings.append((pos,arg))
        if op.name in ('BINFLOAT','FLOAT'): floats.append((pos,arg))
    # find key/value pairs of interest
    out={}
    for j,(pos,s) in enumerate(strings):
        pass
    for idx,(op,arg,pos) in enumerate(ops):
        if op.name in ('SHORT_BINUNICODE','UNICODE','BINUNICODE') and arg in ('id','val_accuracy','framework','epochs'):
            nop=ops[idx+1]
            while nop[0].name=='MEMOIZE':
                nop=ops[idx+2] if False else nop
                break
            # locate next value op after memoizes
            k=idx+1
            while ops[k][0].name=='MEMOIZE': k+=1
            vop,varg=ops[k][0].name,ops[k][1]
            out.setdefault(arg,(vop,varg))
    return globals_set,out

rows=[]
for fn in sorted(glob.glob('model_*.pkl')):
    g,out=safe_scan(fn)
    print('==',fn)
    print('   globals:',sorted(g))
    print('   fields:',out)
EOF"}

